UPDATE video_status
SET   play_times = play_times + 1
WHERE vid = #{vid}

UPDATE video_status
like_times = like_times + 1 unlike_times = unlike_times + 1
WHERE vid = #{vid}

UPDATE video_status
like_times = GREATEST(like_times - 1, 0) unlike_times = GREATEST(unlike_times - 1, 0)
WHERE vid = #{vid}

UPDATE video_status
SET   coin_times = coin_times + #{coin}
WHERE vid = #{vid}

UPDATE video_status
SET   collect_times = collect_times + 1
WHERE vid = #{vid}

UPDATE video_status
SET   collect_times = GREATEST(collect_times - 1, 0)
WHERE vid = #{vid}

UPDATE video_status
SET   share_times = share_times + 1
WHERE vid = #{vid}
